class Solution {
  public int numberOfCombinations(String num) {
    final int MOD = 1_000_000_007;
    int n = num.length();
    char[] s = num.toCharArray();
    // lcp[i][j]: common prefix length of num[i..] and num[j..]; fits a short because n <= 3500
    short[][] lcp = new short[n + 1][n + 1];
    for (int i = n - 1; i >= 0; i--)
      for (int j = n - 1; j >= 0; j--)
        if (s[i] == s[j]) lcp[i][j] = (short) (lcp[i + 1][j + 1] + 1);
    // P[e][l]: number of valid lists for num[0..e) whose last number has length at most l (l <= e)
    int[][] P = new int[n + 1][n + 1];
    for (int e = 1; e <= n; e++) {
      for (int l = 1; l <= e; l++) {
        int start = e - l;
        long w = 0;
        if (s[start] != '0') {
          if (start == 0) w = 1;
          else {
            w = P[start][Math.min(l - 1, start)]; // a shorter previous number is always smaller
            if (l <= start) {
              // an equally long previous number must not be larger
              int c = lcp[start - l][start];
              if (c >= l || s[start - l + c] < s[start + c]) w += P[start][l] - P[start][l - 1] + (long) MOD;
            }
          }
        }
        P[e][l] = (int) ((P[e][l - 1] + w) % MOD);
      }
    }
    return P[n][n];
  }
}
